#include <iostream>
#include <vector>
#include <string>

// Mo phong lop do hoa HT (Hinh Tron / Sprite) voi RAII chuan C++17
class HinhTron {
private:
    int banKinh;
    int mauSac;
    int xHien;
    int yHien;
    bool dangHienThi;
    std::vector<int> duLieuAnh; // Thay the char* pht cap phat bang new

public:
    HinhTron() 
        : banKinh(0), mauSac(0), xHien(0), yHien(0), dangHienThi(false) {}

    HinhTron(int r, int m = 15) 
        : banKinh(r < 0 ? 0 : r), mauSac(m), xHien(0), yHien(0), dangHienThi(false) {
        if (banKinh > 0) {
            // Mo phong imagesize va khoi tao bo nho dem anh
            int size = (banKinh * 2) * (banKinh * 2);
            duLieuAnh.resize(size, mauSac);
        }
    }

    // Ham huy: tu dong goi an() de don dep hien thi truoc khi huy
    ~HinhTron() {
        an();
        std::cout << "[Huy] HinhTron(r=" << banKinh << ") da duoc huy an toan.\n";
    }

    void hien(int x, int y) {
        if (!duLieuAnh.empty() && !dangHienThi) {
            dangHienThi = true;
            xHien = x;
            yHien = y;
            std::cout << "[Hien] Hien thi tai (" << xHien << ", " << yHien 
                      << ") voi ban kinh " << banKinh << ", mau " << mauSac << "\n";
        }
    }

    void an() {
        if (dangHienThi) {
            dangHienThi = false;
            std::cout << "[An] Xoa/an hinh tai vi tri (" << xHien << ", " << yHien << ")\n";
        }
    }
};

int main() {
    std::cout << "--- Bat dau pham vi hoat hoa ---\n";
    {
        HinhTron h1(5, 4);
        h1.hien(10, 10);

        // Khi doi tuong roi khoi pham vi (scope), ham huy tu goi an() va giai phong
        std::cout << "--- Roi khoi pham vi cuc bo ---\n";
    }
    std::cout << "--- Ket thuc chuong trinh ---\n";
    return 0;
}
